
# the gui was generated by an llm, vbut the drawing parts were implemented by me so draw_line, draw_triangle, draw_objects
import tkinter as tk
from tkinter import filedialog, messagebox
from pathlib import Path
from typing import Tuple

from .loader import load_obj_file 
from .mat4 import Mat4
from .vec4 import Vec4
from .transformation_matrices import *
from .indexed_face import IndexedFace

SCREEN_WIDTH = 950
SCREEN_HEIGHT = 650

# PARAMETERS
LINE_COLOR = "blue"
LINE_WIDTH = 1
WIDTH = 900
HEIGHT = 500

#CAMERA = Vec4()
CAMERA_POSITION = Vec4(0,0,0) # check the change
WINDOW_R = 10
WINDOW_L = 10
WINDOW_T = 7.5
WINDOW_B = 7.5
WORLD_TRANSFORMATION = combine_transformation_matrices([
        get_pixel_transformation_matrix(WIDTH,HEIGHT), # pixel conversion
        get_orthographic_transformation_matrix(-WINDOW_L,WINDOW_R,WINDOW_T, -WINDOW_B), # ortographic projection
        get_camera_transformation_matrix(camera_pos=CAMERA_POSITION), # transform for camera
        ])

OBJECT_TRANSFORMATION = get_identity_matrix()


class RendererGUI:
    def __init__(self, root: tk.Tk):
        self.root = root
        self.root.title("3D Renderer")
        self.root.geometry(f"{SCREEN_WIDTH}x{SCREEN_HEIGHT}")
        self.root.minsize(600, 400)

        self.filename = tk.StringVar(value="No file loaded")
        self.vertex_count = tk.StringVar(value="Vertices (v): 0")
        self.face_count = tk.StringVar(value="Faces (f): 0")

        self.vertices = []
        self.faces = []



        # Top toolbar
        toolbar = tk.Frame(root, padx=10, pady=10)
        toolbar.pack(fill="x")

        controls = tk.LabelFrame(root, text="Transformations", padx=10, pady=8)
        controls.pack(fill="x", padx=10, pady=5)

        # Translation
        tk.Label(controls, text="Translate (X, Y, Z):").grid(row=0, column=0, padx=5)
        self.tx = tk.Entry(controls, width=7)
        self.tx.insert(0, "0")
        self.tx.grid(row=0, column=1)

        self.ty = tk.Entry(controls, width=7)
        self.ty.insert(0, "0")
        self.ty.grid(row=0, column=2)

        self.tz = tk.Entry(controls, width=7)
        self.tz.insert(0, "0")
        self.tz.grid(row=0, column=3)

        tk.Button(
            controls, text="Translate", command=self.translate
        ).grid(row=0, column=4, padx=10)

        # Rotation
        tk.Label(controls, text="Rotate (X, Y, Z) rad:").grid(row=1, column=0, padx=5)
        self.rx = tk.Entry(controls, width=7)
        self.rx.insert(0, "0")
        self.rx.grid(row=1, column=1)

        self.ry = tk.Entry(controls, width=7)
        self.ry.insert(0, "0")
        self.ry.grid(row=1, column=2)

        self.rz = tk.Entry(controls, width=7)
        self.rz.insert(0, "0")
        self.rz.grid(row=1, column=3)

        tk.Button(
            controls, text="Rotate", command=self.rotate
        ).grid(row=1, column=4, padx=10)

        # Uniform scaling
        tk.Label(controls, text="Scale:").grid(row=2, column=0, padx=5)
        self.scale = tk.Entry(controls, width=7)
        self.scale.insert(0, "1")
        self.scale.grid(row=2, column=1)

        tk.Button(
            controls, text="Scale", command=self.scale_model
        ).grid(row=2, column=4, padx=10)
        
        tk.Button(
            toolbar,
            text="Load OBJ",
            command=self.load_file,
            padx=15,
        ).pack(side="left")

        tk.Button(
            toolbar,
            text="Reset",
            command=self.reset,
            padx=15,
        ).pack(side="left", padx=5)

        tk.Label(
            toolbar,
            textvariable=self.filename,
            anchor="w",
        ).pack(side="left", padx=15, fill="x", expand=True)

        ## Model statistics
        #stats = tk.Frame(root, padx=10, pady=5)
        #stats.pack(fill="x")

        tk.Label(
            toolbar,
            textvariable=self.vertex_count,
            font=("TkDefaultFont", 11, "bold"),
        ).pack(side="left", padx=(0, 30))

        tk.Label(
            toolbar,
            textvariable=self.face_count,
            font=("TkDefaultFont", 11, "bold"),
        ).pack(side="left")

        # Drawing area
        self.canvas = tk.Canvas(
            root,
            width=WIDTH,
            height=HEIGHT,
            background="#20242b",
            highlightthickness=0,
        )
        self.canvas.pack(
            #fill="both",
            #expand=True,
            padx=10,
            pady=(5, 10),
        )

        # Example placeholder
        self.canvas.create_text(
            20, 20,
            text="Load an OBJ file to begin",
            fill="white",
            anchor="nw",
            tags="placeholder",
        )

    def load_file(self):
        path = filedialog.askopenfilename(
            parent=self.root,
            title="Select OBJ file",
            filetypes=[
                ("Wavefront OBJ files", "*.obj"),
                ("All files", "*.*"),
            ],
        )

        if not path:
            return

        try:
            vertices, faces = load_obj_file(path)
        except (OSError, UnicodeError, ValueError) as error:
            messagebox.showerror(
                "OBJ loading failed",
                str(error),
                parent=self.root,
            )
            return

        # Update state only after successful loading.
        self.indexed_face = IndexedFace(vertices,faces)

        self.filename.set(Path(path).name)
        self.vertex_count.set(f"Vertices (v): {len(vertices)}")
        self.face_count.set(f"Faces (f): {len(faces)}")

        self.canvas.delete("placeholder")
    

        # Drawing the model will go here later.
        self.draw_objects()

    def draw_objects(self):
        self.canvas.delete("model")
        vertices = self.indexed_face.get_vertices()

        
        
        for face in self.indexed_face.get_faces():
            p1:Vec4 = vertices[face[0]]
            p2:Vec4 = vertices[face[1]]
            p3:Vec4 = vertices[face[2]]


            p1 = WORLD_TRANSFORMATION*OBJECT_TRANSFORMATION*p1
            p2 = WORLD_TRANSFORMATION*OBJECT_TRANSFORMATION*p2
            p3 = WORLD_TRANSFORMATION*OBJECT_TRANSFORMATION*p3

            self.draw_line(p1,p2)
            self.draw_line(p2,p3)
            self.draw_line(p3,p1)


    def draw_line(self,p1: Vec4, p2: Vec4):
        global LINE_COLOR, LINE_WIDTH

        x1,y1 = p1[0], p1[1]
        x2,y2 = p2[0], p2[1]

        self.canvas.create_line(x1,y1,x2,y2, fill=LINE_COLOR, width=LINE_WIDTH, tag="model")

    def draw_triangle(self,points: Tuple[Vec4, Vec4, Vec4] ):

        x1,y1 = points[0][0], points[0][1]
        x2,y2 = points[1][0], points[1][1]
        x3,y3 = points[2][0], points[2][1]
        
        self.canvas.create_polygon(
            x1,y1,x2,y2,x3,y3,
            outline="cyan",
            fill="",
            width=1,
            tags="model",
        )

    def translate(self):
        tx, ty, tz = float(self.tx.get()), float(self.ty.get()), float(self.tz.get())
        # Apply your translation matrix and redraw.
        self.apply_matrix(get_translation_matrix(tx, ty, tz))


    def rotate(self):
        rx, ry, rz = float(self.rx.get()), float(self.ry.get()), float(self.rz.get())
        # Apply your rotation matrices and redraw.
        self.apply_matrix(combine_transformation_matrices([
            get_rotation_x_axis_matrix(rx),
            get_rotation_y_axis_matrix(ry),
            get_rotation_z_axis_matrix(rz),
        ]))


    def scale_model(self):
        factor = float(self.scale.get())
        # Apply your scaling matrix and redraw.
        self.apply_matrix(get_scaling_matrix(factor,factor,factor))

    def apply_matrix(self, matrix:Mat4):
        global OBJECT_TRANSFORMATION
        OBJECT_TRANSFORMATION = matrix * OBJECT_TRANSFORMATION
        self.draw_objects()

    def reset(self):
        global OBJECT_TRANSFORMATION
        print("RESET")
        self.tx.delete(0, tk.END)
        self.tx.insert(0, "0")
        self.ty.delete(0, tk.END)
        self.ty.insert(0, "0")
        self.tz.delete(0, tk.END)
        self.tz.insert(0, "0")

        self.rx.delete(0, tk.END)
        self.rx.insert(0, "0")
        self.ry.delete(0, tk.END)
        self.ry.insert(0, "0")
        self.rz.delete(0, tk.END)
        self.rz.insert(0, "0")

        self.scale.delete(0, tk.END)
        self.scale.insert(0, "1")

        OBJECT_TRANSFORMATION = get_identity_matrix()
        self.draw_objects()

